"""Meridian CRM 4.2 RBAC permission check migration."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform the action on the record."""
    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    # Blank CHAR(1) booleans have the legacy value 'N'.
    del_flg = record.get("DEL_FLG", "") or "N"
    if action == "DELETE" and del_flg != "N":
        return False

    # Iterate in supplied rule-file order and deny if no row matches.
    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # ADMIN bypasses scope only; reaching here confirms a row exists.
        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user_team == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user_id == record.get("OWNER_UID", "")
        return False  # NONE or an unrecognized scope denies.

    return False
